syntax = "proto2";
package mahjong;

enum Command
{
    cmd_place_holder = 0;
    S2C_LoginError = 0x1005; //登录错误
    S2C_LoginSucc = 0x1007; //登录房间成功 通知自己
    S2C_LogoutSucc = 0x1008; //退出房间成功 通知自己
    S2C_ReconnSucc = 0x1009; //重连成功
    S2C_UserEnterRoom = 0x100D; //玩家进入房间 通知其他玩家
    S2C_UserQuitRoom = 0x100E; //玩家退出房间
    S2C_UserReadyStatus = 0x4001; //玩家准备状态
    S2C_UserAutoStatus = 0x4007; //玩家托管状态
    
    S2C_SystemError = 0x5000;
    S2C_GameStart = 0x5001;   
    S2C_DingLaiZi = 0x5002;  //定癞子
    S2C_DingZhuang = 0x5003; //定庄
    S2C_ZhiTou = 0x5004; //掷骰
    S2C_DealCard = 0x5005; //拿牌
    C2S_HuanSanZhang = 0x5006; //换三张
    S2C_HuanSanZhang = 0x5007;
    C2S_DingQue = 0x5008; //定缺
    S2C_DingQue = 0x5009;
    S2C_PlayOption = 0x5010; //可操作选项
    C2S_OutCard = 0x5011; //玩家出牌
    S2C_OutCardResult = 0x5012; //出牌结果
    S2C_GrabCard = 0x5013; //抓牌
    S2C_WaitOtherOperation = 0x5014; //等待其他玩家操作
    S2C_SettleMoney = 0x5015; //结算流水
    S2C_Settle = 0x5016; //结算消息
    S2C_GameOver = 0x5017; //游戏结束
    C2S_WithdrawMoney = 0x5018; //玩家取钱消息
    S2C_WithdrawMoney = 0x5019; //服务端返回取钱结果
    C2S_HuanSanZhangPick = 0x5020; //组队模式玩家选牌
    S2C_HuanSanZhangPick = 0x5021; 
};

// S2C_LoginError
message RspLoginError 
{
    optional string reason = 1;
    optional uint32 errcode = 2;
};

message RoomInfo 
{
    optional uint32 level = 1;
    optional uint32 basechip = 2;
    optional uint32 deskfee = 3;
    optional uint32 total_game = 4;
};

message RoomUserInfo 
{
    optional uint32 uid = 1;
    optional uint32 seatid = 2;
    optional bool ready = 3;
    optional bool ai = 4; //是否托管
    optional uint64 moneyOld = 5;
    optional string userinfo = 6; //json格式
    optional int64 money = 7;
    optional int64 team_money = 8; //组队银币
};

// S2C_LoginSucc
message RspLoginSuccess
{
    optional RoomInfo room_info = 1;
    optional RoomUserInfo self_info = 2;
    repeated RoomUserInfo others = 3;
};

// S2C_LogoutSucc
message RspLogoutSuccess 
{
    optional uint32 uid = 1; //退出玩家uid
};

// S2C_ReconnSucc
message RspReconnSuccess
{
    optional uint32 opuid = 1;
    optional uint32 optime = 2;
    optional uint32 banker_uid = 3;
    optional RoomInfo room_info = 4;  
    repeated RoomUserInfo user_info = 5;
    repeated HuanSanZhangData huansanzhang = 6;
    repeated DingQueData dingque = 7;
    repeated PlayerCardData tabledata = 8;
    repeated RspSettleMoney money_flow = 9;
    optional uint32 mahjongwall_size = 10; 
    optional OptionTing ting_tips = 11;
    optional uint32 round_uid = 12;
    repeated WithdrawUserData giveup = 13;
};

// S2C_UserEnterRoom
message RspUserEnterRoom 
{
    optional RoomUserInfo userinfo = 1;
};

// S2C_UserQuitRoom
message RspUserQuitRoom
{
    optional uint32 uid = 1;
};

// S2C_UserReadyStatus
message RspUserReadyStatus
{
    optional uint32 uid = 1;
    optional bool ready = 2; // 0-未准备 1-准备 
};

// S2C_UserAutoStatus
message RspUserAutoStatus
{
    optional uint32 uid = 1;
    optional bool ai = 2; //0-未托管 1-托管
};

/////////////////////////////////////////////////////////////////////////

//对局出现异常，对局会结束
message SystemError 
{
    optional uint32 errcode = 1;
    optional string reason = 2;
};

// S2C_GameStart
message RspGameStart 
{
    optional uint32 desc = 1;
};

//S2C_DingLaiZi
message RspDingLaiZi 
{
    optional uint32 laizi_card = 1;
};

//S2C_DingZhuang
message RspDingZhuang 
{
    optional uint32 banker_uid = 1;
};

//S2C_ZhiTou
message RspZhiTou 
{
    repeated uint32 points = 1;
};

message PlayerCardData
{
    optional uint32 uid = 1;
    optional uint32 handcard_num = 2; //手牌数量
    repeated uint32 handcards = 3; //手牌

    repeated OptionChi chi_cards = 4; //吃牌
    repeated OptionPeng peng_cards = 5; //碰牌
    repeated OptionGang gang_cards = 6; //杠牌
    repeated OptionHu hu_cards = 7; //胡牌区
    repeated uint32 out_cards = 8; //打出的牌
};

//S2C_DealCard
message RspDealCard 
{
    repeated PlayerCardData cards = 1;
    optional uint32 mjwall_num = 2;
};

//C2S_HuanSanZhang
message ReqHuanSanZhang 
{
    optional uint32 uid = 1;
    repeated uint32 cards = 2;
};

message HuanSanZhangData 
{
    optional uint32 uid = 1;  //自己uid
    optional uint32 to_uid = 2;  //自己给这个玩家提供牌
    repeated uint32 cards = 3;  //自己提供的牌
};

//S2C_HuanSanZhang
message RspHuanSanZhang
{
    optional uint32 opt = 1;    // 1-换三张开始  2-换三张提交手牌结果 3-换三张最终结果
    optional uint32 optime = 2; // opt==1 换三张操作时间
    optional uint32 commit_ret = 3; //opt==2 换三张提交结果  0-成功  非0-参考ErrCode错误码定义
    optional uint32 commit_uid = 4; //opt==2 提交的玩家uid
    repeated uint32 commit_cards = 5; //opt==2 提交手牌 
    repeated HuanSanZhangData data = 6; //opt==3 或 opt==1
};

//C2S_DingQue
message ReqDingQue 
{
    optional uint32 uid = 1;
    optional uint32 select = 2; // 0-万 1-筒 2-条
};

message DingQueData 
{
    optional uint32 uid = 1;
    optional uint32 select = 2; // 0-万 1-筒 2-条
};

//S2C_DingQue
message RspDingQue 
{
    optional uint32 opt = 1; // 1-定缺开始 2-定缺最终结果
    optional uint32 optime = 2; //opt==1 定缺时间
    repeated DingQueData data = 5; //opt==1建议 opt==2定缺选择结果
};

message OptionOutCard 
{
    optional uint32 card = 1; //出的牌
};

message OptionChi 
{
    optional uint32 type = 1; // 1003-左吃 1002-中吃 1001-右吃
    optional uint32 chi_card = 2; // 吃的牌
    optional uint32 from_uid = 3; //被吃玩家id
    repeated uint32 cards = 4; //牌组
};

message OptionPeng 
{
    optional uint32 from_uid = 1; //被碰玩家
    optional uint32 peng_card = 2; //碰的牌
    repeated uint32 cards = 3; //牌组
};

message OptionGang 
{
    optional uint32 type = 1; //3001-直杠 3003-暗杠 3004-补杠 
    optional uint32 gang_card = 2; //杠的牌
    repeated uint32 cards = 3; //牌组
    optional uint32 from_uid = 4; //直杠时被杠玩家
};

message FanInfo 
{
    optional uint32 type = 1; //类型
    optional uint32 fan = 2; //番数
};

message TingItem
{
    optional uint32 hu_card = 1; //胡的牌
    optional FanInfo pai_xing = 2; //基础牌型
    repeated FanInfo extend_fan = 3; //拓展番
    optional uint32 remain_num = 4; //剩余数量
};

message OptionTing
{
    optional uint32 out_card = 1; //打出的牌
    repeated TingItem items = 2; //能听的组合
};

message OptionHu 
{
    optional uint32 type = 1; //4001-点炮 4002-抢杠胡 4004-自摸
    optional uint32 hu_card = 2; //胡的牌
    optional bool valid = 3; //标记hu_card是否 计入有效牌数 
    optional uint32 pao_uid = 4; //点炮玩家uid
    repeated uint32 cards = 5; //牌组
    optional FanInfo pai_xing = 6; //基础牌型
    repeated FanInfo extend_fan = 7; //拓展番
    optional uint32 remain_num = 8; //剩余数量
};

//S2C_PlayOption 可操作选项
message RspPlayOption 
{
    optional uint32 optime = 1; //操作时间
    repeated uint32 options = 2; //可选操作列表
    repeated OptionOutCard opt_out = 3; //可出牌组
    repeated OptionChi opt_chi = 4; 
    repeated OptionPeng opt_peng = 5;
    repeated OptionGang opt_gang = 6;
    repeated OptionTing opt_ting = 7;
    repeated OptionHu opt_hu = 8;
    optional uint32 uid = 9;
    optional uint32 round_uid = 10; //当前回合玩家uid
};

message UserOption
{
    optional uint32 uid = 1;
    optional uint32 op_code = 2; //操作码
    optional OptionOutCard outcard_info = 3; //出牌
    optional OptionChi chi_info = 4; //吃
    optional OptionPeng peng_info = 5; //碰
    optional OptionGang gang_info = 6; //杠
    optional OptionTing ting_info = 7; //听
    optional OptionHu hu_info = 8; //胡
    optional uint32 grab_card = 9; //deprecated 抓牌
};

//C2S_OutCard 玩家操作 从RspPlayOption中选择一项进行操作
message ReqOutCard 
{
    optional uint32 op_code = 1; //操作码
    optional uint32 index = 2; //吃碰杠听胡数组中的索引
    optional uint32 subidx = 3; 
};

//S2C_OutCardResult 玩家操作结果
message RspOutCard 
{
    optional uint32 err_code = 1; // 0-操作正常 非0-参考错误码
    optional UserOption user_op = 2; // 玩家操作
};

//S2C_GrabCard 抓牌
message RspGrabCard 
{
    optional uint32 uid = 1;
    optional uint32 grab_card = 2; //摸的牌，仅自己可见
    optional uint32 handcard_num = 3; //摸牌后手牌数量
    optional uint32 remain_num = 4; //牌墙剩余数量
};

// S2C_WaitOtherOperation 等待其他玩家操作
message RspWaitOtherOperation
{
    optional uint32 param = 1;
    optional uint32 type = 2; //0-不显示等待 1-玩家可操作,点取消后显示等待
};

message MoneyItem 
{
    optional uint32 uid = 1;
    optional int64 turn_money = 2;
}

// S2C_SettleMoney 结算流水
message RspSettleMoney 
{
    //3001-直杠 3003-暗杠 3004-补杠 
    //4001-点炮 4002-抢杠胡 4004-自摸
    //100-退杠钱 101-查花猪 102-查叫 103-台费
    optional uint32 type = 1; 
    optional uint32 uid = 2;  //赢钱玩家
    optional uint32 pao_uid = 3; //点炮或放杠玩家
    repeated MoneyItem items = 4; 
    optional OptionHu huinfo = 5; //仅type胡时有数据
};

// S2C_Settle 结算消息
message RspSettle 
{
    repeated PlayerCardData userdata = 1; //玩家牌数据,不包含吃碰和打出去的牌
    repeated MoneyItem tui_gang = 2;
    repeated MoneyItem hua_zhu = 3;
    repeated MoneyItem cha_jiao = 4;
    repeated MoneyItem real_money = 5; //组队模式,玩家真实资产
    repeated MoneyItem turn_money = 6; //组队模式下,玩家输赢钱
};

// S2C_GameOver
message RspGameOver 
{
    optional uint32 param = 1;
};

message WithdrawUserData
{
    optional uint32 uid = 1;
    optional uint32 choose = 2;  // 1-取钱完成  2-放弃取钱(破产旁观)
    optional int64 money = 3; //取钱后的钱 放弃则为0
}

// C2S_WithdrawMoney
message ReqWithdrawMoney 
{
    optional uint32 choose = 1; // 1-取钱完成  2-放弃取钱(破产旁观)
};

// S2C_WithdrawMoney
message RspWithdrawMoney 
{
    optional uint32 opt = 1; //1-通知玩家取钱  2-玩家取钱结果 
    optional uint32 optime = 2; //opt==1 破产取钱时间
    repeated uint32 bankrupt_users = 3; //opt==1 破产玩家
    optional WithdrawUserData data = 4; //opt==2 玩家选择结果
};

// C2S_HuanSanZhangPick
message ReqHuanSanZhangPick 
{
    optional uint32 uid = 1; //自己选牌
    repeated uint32 pickcards = 2; //选的牌
}

// S2C_HuanSanZhangPick
message RspHuanSanZhangPick 
{
    optional uint32 uid = 1; //队友选牌
    repeated uint32 pickcards = 2;
}
